const { Queue } = require('bullmq');
const exportQueue = new Queue('data-exports', { connection: redisOptions });

app.get('/api/exports/:jobId/download', authenticateUser, async (req, res) => {
  const job = await exportQueue.getJob(req.params.jobId);
  if (!job) return res.status(404).json({ error: 'Export job not found' });
  if (job.data.requestedBy !== req.user.id && !req.user.isAdmin) {
    return res.status(403).json({ error: 'Unauthorized to download this export' });
  }
  if (!job.returnvalue || !job.returnvalue.s3PresignedUrl) {
    return res.status(400).json({ status: 'Job still processing or failed' });
  }
  res.json({ downloadUrl: job.returnvalue.s3PresignedUrl });
});
